17	package org.apache.camel.component.seda;
18	
19	import java.io.IOException;
20	import java.util.concurrent.BlockingQueue;
21	import java.util.concurrent.CountDownLatch;
22	import java.util.concurrent.TimeUnit;
23	
24	import org.apache.camel.AsyncCallback;
25	import org.apache.camel.Exchange;
26	import org.apache.camel.ExchangeTimedOutException;
27	import org.apache.camel.StreamCache;
28	import org.apache.camel.WaitForTaskToComplete;
29	import org.apache.camel.support.DefaultAsyncProducer;
30	import org.apache.camel.support.ExchangeHelper;
31	import org.apache.camel.support.SynchronizationAdapter;
32	import org.slf4j.Logger;
33	import org.slf4j.LoggerFactory;
34	
35	public class SedaProducer extends DefaultAsyncProducer {
36	
37	    private static final Logger LOG = LoggerFactory.getLogger(SedaProducer.class);
38	    private final SedaEndpoint endpoint;
39	    private final WaitForTaskToComplete waitForTaskToComplete;
40	    private final long timeout;
41	    private final boolean blockWhenFull;
42	    private final boolean discardWhenFull;
43	    private final long offerTimeout;
44	
45	    public SedaProducer(SedaEndpoint endpoint, WaitForTaskToComplete waitForTaskToComplete,
46	                        long timeout, boolean blockWhenFull, boolean discardWhenFull, long offerTimeout) {
47	        super(endpoint);
48	        this.endpoint = endpoint;
49	        this.waitForTaskToComplete = waitForTaskToComplete;
50	        this.timeout = timeout;
51	        this.blockWhenFull = blockWhenFull;
52	        this.discardWhenFull = discardWhenFull;
53	        this.offerTimeout = offerTimeout;
54	    }
55	
56	    @Override
57	    public boolean process(final Exchange exchange, final AsyncCallback callback) {
58	        WaitForTaskToComplete wait = waitForTaskToComplete;
59	        if (exchange.getProperty(Exchange.ASYNC_WAIT) != null) {
60	            wait = exchange.getProperty(Exchange.ASYNC_WAIT, WaitForTaskToComplete.class);
61	        }
62	
63	        if (wait == WaitForTaskToComplete.Always
64	                || wait == WaitForTaskToComplete.IfReplyExpected && ExchangeHelper.isOutCapable(exchange)) {
65	
66	            // do not handover the completion as we wait for the copy to complete, and copy its result back when it done
67	            Exchange copy = prepareCopy(exchange, false);
68	
69	            // latch that waits until we are complete
70	            final CountDownLatch latch = new CountDownLatch(1);
71	
72	            // we should wait for the reply so install a on completion so we know when its complete
73	            copy.getExchangeExtension().addOnCompletion(new SynchronizationAdapter() {
74	                @Override
75	                public void onDone(Exchange response) {
76	                    // check for timeout, which then already would have invoked the latch
77	                    if (latch.getCount() == 0) {
78	                        if (LOG.isTraceEnabled()) {
79	                            LOG.trace("{}. Timeout occurred so response will be ignored: {}", this, response.getMessage());
80	                        }
81	                        return;
82	                    } else {
83	                        if (LOG.isTraceEnabled()) {
84	                            LOG.trace("{} with response: {}", this, response.getMessage());
85	                        }
86	                        try {
87	                            ExchangeHelper.copyResults(exchange, response);
88	                        } finally {
89	                            // always ensure latch is triggered
90	                            latch.countDown();
91	                        }
92	                    }
93	                }
94	
95	                @Override
96	                public boolean allowHandover() {
97	                    // do not allow handover as we want to seda producer to have its completion triggered
98	                    // at this point in the routing (at this leg), instead of at the very last (this ensure timeout is honored)
99	                    return false;
100	                }
101	
102	                @Override
103	                public String toString() {
104	                    return "onDone at endpoint: " + endpoint;
105	                }
106	            });
107	
108	            try {
109	                // do not copy as we already did the copy
110	                addToQueue(copy, false);
111	            } catch (SedaConsumerNotAvailableException | IOException e) {
112	                exchange.setException(e);
113	                callback.done(true);
114	                return true;
115	            }
116	
117	            if (timeout > 0) {
118	                if (LOG.isTraceEnabled()) {
119	                    LOG.trace("Waiting for task to complete using timeout (ms): {} at [{}]", timeout,
120	                            endpoint.getEndpointUri());
121	                }
122	                // lets see if we can get the task done before the timeout
123	                boolean done = false;
124	                try {
125	                    done = latch.await(timeout, TimeUnit.MILLISECONDS);
126	                } catch (InterruptedException e) {
127	                    Thread.currentThread().interrupt();
128	                }
129	                if (!done) {
130	                    exchange.setException(new ExchangeTimedOutException(exchange, timeout));
131	                    // remove timed out Exchange from queue
132	                    endpoint.getQueue().remove(copy);
133	                    // count down to indicate timeout
134	                    latch.countDown();
135	                }
136	            } else {
137	                if (LOG.isTraceEnabled()) {
138	                    LOG.trace("Waiting for task to complete (blocking) at [{}]", endpoint.getEndpointUri());
139	                }
140	                // no timeout then wait until its done
141	                try {
142	                    latch.await();
143	                } catch (InterruptedException e) {
144	                    Thread.currentThread().interrupt();
145	                }
146	            }
147	        } else {
148	            // no wait, eg its a InOnly then just add to queue and return
149	            try {
150	                addToQueue(exchange, true);
151	            } catch (SedaConsumerNotAvailableException | IOException e) {
152	                exchange.setException(e);
153	                callback.done(true);
154	                return true;
155	            }
156	        }
157	
158	        // we use OnCompletion on the Exchange to callback and wait for the Exchange to be done
159	        // so we should just signal the callback we are done synchronously
160	        callback.done(true);
161	        return true;
162	    }
163	
164	    protected Exchange prepareCopy(Exchange exchange, boolean handover) {
165	        // use a new copy of the exchange to route async (and use same message id)
166	        // if handover we need to do special handover to avoid handing over
167	        // RestBindingMarshalOnCompletion as it should not be handed over with SEDA
168	        return ExchangeHelper.createCorrelatedCopy(exchange, handover, true);
169	    }
170	
171	    @Override
172	    protected void doStart() throws Exception {
173	        super.doStart();
174	        endpoint.onStarted(this);
175	    }
176	
177	    @Override
178	    protected void doStop() throws Exception {
179	        endpoint.onStopped(this);
180	        super.doStop();
181	    }
182	
183	    /**
184	     * Strategy method for adding the exchange to the queue.
185	     * <p>
186	     * Will perform a blocking "put" if blockWhenFull is true, otherwise it will simply add which will throw exception
187	     * if the queue is full
188	     *
189	     * @param exchange the exchange to add to the queue
190	     * @param copy     whether to create a copy of the exchange to use for adding to the queue
191	     */
192	    protected void addToQueue(Exchange exchange, boolean copy) throws SedaConsumerNotAvailableException, IOException {
193	        BlockingQueue<Exchange> queue = null;
194	        QueueReference queueReference = endpoint.getQueueReference();
195	        if (queueReference != null) {
196	            queue = queueReference.getQueue();
197	        }
198	        if (queue == null) {
199	            throw new SedaConsumerNotAvailableException("No queue available on endpoint: " + endpoint, exchange);
200	        }
201	
202	        boolean empty = !queueReference.hasConsumers();
203	        if (empty) {
204	            if (endpoint.isFailIfNoConsumers()) {
205	                throw new SedaConsumerNotAvailableException("No consumers available on endpoint: " + endpoint, exchange);
206	            } else if (endpoint.isDiscardIfNoConsumers()) {
207	                LOG.debug("Discard message as no active consumers on endpoint: {}", endpoint);
208	                return;
209	            }
210	        }
211	
212	        Exchange target = exchange;
213	
214	        // handover the completion so its the copy which performs that, as we do not wait
215	        if (copy) {
216	            target = prepareCopy(exchange, true);
217	            // if the body is stream caching based we need to make a deep copy
218	            if (target.getMessage().getBody() instanceof StreamCache sc) {
219	                StreamCache newBody = sc.copy(target);
220	                if (newBody != null) {
221	                    target.getMessage().setBody(newBody);
222	                }
223	            }
224	        }
225	
226	        LOG.trace("Adding Exchange to queue: {}", target);
227	        if (discardWhenFull) {
228	            try {
229	                boolean added = queue.offer(target, 0, TimeUnit.MILLISECONDS);
230	                if (!added) {
231	                    LOG.trace("Discarding Exchange as queue is full: {}", target);
232	                }
233	            } catch (InterruptedException e) {
234	                LOG.debug("Offer interrupted, are we stopping? {}", isStopping() || isStopped());
235	                Thread.currentThread().interrupt();
236	            }
237	        } else if (blockWhenFull && offerTimeout == 0) {
238	            try {
239	                queue.put(target);
240	            } catch (InterruptedException e) {
241	                LOG.debug("Put interrupted, are we stopping? {}", isStopping() || isStopped());
242	                Thread.currentThread().interrupt();
243	            }
244	        } else if (blockWhenFull && offerTimeout > 0) {
245	            try {
246	                boolean added = queue.offer(target, offerTimeout, TimeUnit.MILLISECONDS);
247	                if (!added) {
248	                    throw new IllegalStateException(
249	                            "Fails to insert element into queue, "
250	                                                    + "after timeout of " + offerTimeout + " milliseconds");
251	                }
252	            } catch (InterruptedException e) {
253	                // ignore
254	                LOG.debug("Offer interrupted, are we stopping? {}", isStopping() || isStopped());
255	                Thread.currentThread().interrupt();
256	            }
257	        } else {
258	            queue.add(target);
259	        }
260	    }
261	
262	}
