17	package org.apache.camel.component.seda;
18	
19	import java.util.ArrayList;
20	import java.util.HashSet;
21	import java.util.List;
22	import java.util.Set;
23	import java.util.concurrent.BlockingQueue;
24	import java.util.concurrent.CopyOnWriteArraySet;
25	import java.util.concurrent.ExecutorService;
26	
27	import org.apache.camel.AsyncEndpoint;
28	import org.apache.camel.AsyncProcessor;
29	import org.apache.camel.Category;
30	import org.apache.camel.Component;
31	import org.apache.camel.Consumer;
32	import org.apache.camel.Exchange;
33	import org.apache.camel.MultipleConsumersSupport;
34	import org.apache.camel.PollingConsumer;
35	import org.apache.camel.Processor;
36	import org.apache.camel.Producer;
37	import org.apache.camel.WaitForTaskToComplete;
38	import org.apache.camel.api.management.ManagedAttribute;
39	import org.apache.camel.api.management.ManagedOperation;
40	import org.apache.camel.api.management.ManagedResource;
41	import org.apache.camel.spi.BrowsableEndpoint;
42	import org.apache.camel.spi.Metadata;
43	import org.apache.camel.spi.UriEndpoint;
44	import org.apache.camel.spi.UriParam;
45	import org.apache.camel.spi.UriPath;
46	import org.apache.camel.support.DefaultEndpoint;
47	import org.apache.camel.support.PluginHelper;
48	import org.apache.camel.support.service.ServiceHelper;
49	import org.apache.camel.util.URISupport;
50	import org.slf4j.Logger;
51	import org.slf4j.LoggerFactory;
52	
53	/**
54	 * Asynchronously call another endpoint from any Camel Context in the same JVM.
55	 */
56	@ManagedResource(description = "Managed SedaEndpoint")
57	@UriEndpoint(firstVersion = "1.1.0", scheme = "seda", title = "SEDA", syntax = "seda:name",
58	             remote = false, category = { Category.CORE, Category.MESSAGING })
59	public class SedaEndpoint extends DefaultEndpoint implements AsyncEndpoint, BrowsableEndpoint, MultipleConsumersSupport {
60	
61	    private static final Logger LOG = LoggerFactory.getLogger(SedaEndpoint.class);
62	
63	    private final Set<SedaProducer> producers = new CopyOnWriteArraySet<>();
64	    private final Set<SedaConsumer> consumers = new CopyOnWriteArraySet<>();
65	    private volatile AsyncProcessor consumerMulticastProcessor;
66	    private volatile boolean multicastStarted;
67	    private volatile ExecutorService multicastExecutor;
68	
69	    @UriPath(description = "Name of queue")
70	    @Metadata(required = true)
71	    private String name;
72	    @UriParam(label = "advanced", description = "Define the queue instance which will be used by the endpoint")
73	    private BlockingQueue<Exchange> queue;
74	    @UriParam(defaultValue = "" + SedaConstants.QUEUE_SIZE,
75	              description = "The maximum capacity of the SEDA queue (i.e., the number of messages it can hold). Will by default use the"
76	                            + " queueSize set on the SEDA component.")
77	    private int size = SedaConstants.QUEUE_SIZE;
78	    @UriParam(label = "advanced", defaultValue = "100",
79	              description = "Maximum number of messages to keep in memory available for browsing. Use 0 for unlimited.")
80	    private int browseLimit = 100;
81	
82	    @UriParam(label = "consumer", defaultValue = "1",
83	              description = "Number of concurrent threads processing exchanges."
84	                            + " When virtualThreadPerTask is enabled, this becomes a concurrency limit"
85	                            + " (0 = unlimited) and defaults to 0 instead of 1.")
86	    private int concurrentConsumers = 1;
87	    @UriParam(label = "consumer,advanced", defaultValue = "true",
88	              description = "Whether to limit the number of concurrentConsumers to the maximum of 500. By default, an exception will be thrown"
89	                            + " if an endpoint is configured with a greater number. You can disable that check by turning this option off.")
90	    private boolean limitConcurrentConsumers = true;
91	    @UriParam(label = "consumer,advanced",
92	              description = "Specifies whether multiple consumers are allowed. If enabled, you can use SEDA for Publish-Subscribe messaging."
93	                            + " That is, you can send a message to the SEDA queue and have each consumer receive a copy of the message. When"
94	                            + " enabled, this option should be specified on every consumer endpoint.")
95	    private boolean multipleConsumers;
96	    @UriParam(label = "consumer,advanced",
97	              description = "Whether to purge the task queue when stopping the consumer/route. This allows to stop faster, as any pending"
98	                            + " messages on the queue is discarded.")
99	    private boolean purgeWhenStopping;
100	    @UriParam(label = "consumer,advanced", defaultValue = "1000",
101	              description = "The timeout (in milliseconds) used when polling. When a timeout occurs, the consumer can check whether it is"
102	                            + " allowed to continue running. Setting a lower value allows the consumer to react more quickly upon shutdown.")
103	    private int pollTimeout = 1000;
104	    @UriParam(label = "consumer,advanced",
105	              description = "If enabled, spawns a new virtual thread for each message instead of using a fixed pool of consumer threads. "
106	                            + "This model is optimized for virtual threads (JDK 21+) and I/O-bound workloads where creating threads is cheap. "
107	                            + "The concurrentConsumers option becomes a limit on max concurrent tasks (0 = unlimited). "
108	                            + "Requires virtual threads to be enabled via camel.threads.virtual.enabled=true.")
109	    private boolean virtualThreadPerTask;
110	
111	    @UriParam(label = "producer", defaultValue = "IfReplyExpected",
112	              description = "Option to specify whether the caller should wait for the async task to complete or not before continuing. The"
113	                            + " following three options are supported: Always, Never or IfReplyExpected. The first two values are"
114	                            + " self-explanatory. The last value, IfReplyExpected, will only wait if the message is Request Reply based. The"
115	                            + " default option is IfReplyExpected.")
116	    private WaitForTaskToComplete waitForTaskToComplete = WaitForTaskToComplete.IfReplyExpected;
117	    @UriParam(label = "producer", defaultValue = "30000", javaType = "java.time.Duration",
118	              description = "Timeout before a SEDA producer will stop waiting for an asynchronous task to complete. You can"
119	                            + " disable timeout by using 0 or a negative value.")
120	    private long timeout = 30000;
121	    @UriParam(label = "producer,advanced", javaType = "java.time.Duration",
122	              description = "Offer timeout can be added to the block case when queue is full. You can disable timeout by"
123	                            + " using 0 or a negative value.")
124	    private long offerTimeout;
125	    @UriParam(label = "producer,advanced",
126	              description = "Whether a thread that sends messages to a full SEDA queue will block until the queue's capacity is no longer"
127	                            + " exhausted. By default, an exception will be thrown stating that the queue is full. By enabling this option, the"
128	                            + " calling thread will instead block and wait until the message can be accepted.")
129	    private boolean blockWhenFull;
130	    @UriParam(label = "producer,advanced",
131	              description = "Whether a thread that sends messages to a full SEDA queue will be discarded. By default, an exception will be"
132	                            + " thrown stating that the queue is full. By enabling this option, the calling thread will give up sending and"
133	                            + " continue, meaning that the message was not sent to the SEDA queue.")
134	    private boolean discardWhenFull;
135	    @UriParam(label = "producer,advanced",
136	              description = "Whether the producer should fail by throwing an exception, when sending to a queue with no active consumers."
137	                            + " Only one of the options discardIfNoConsumers and failIfNoConsumers can be enabled at the same time.")
138	    private boolean failIfNoConsumers;
139	    @UriParam(label = "producer,advanced",
140	              description = "Whether the producer should discard the message (do not add the message to the queue), when sending to a queue"
141	                            + " with no active consumers. Only one of the options discardIfNoConsumers and failIfNoConsumers can be enabled at the same time.")
142	    private boolean discardIfNoConsumers;
