193	    @Override
194	    public Consumer createConsumer(Processor processor) throws Exception {
195	        if (getComponent() != null) {
196	            // all consumers must match having the same multipleConsumers options
197	            String key = getComponent().getQueueKey(getEndpointUri());
198	            QueueReference ref = getComponent().getQueueReference(key);
199	            if (ref != null && ref.getMultipleConsumers() != isMultipleConsumers()) {
200	                // there is already a multiple consumers, so make sure they matches
201	                throw new IllegalArgumentException(
202	                        "Cannot use existing queue " + key + " as the existing queue multiple consumers "
203	                                                   + ref.getMultipleConsumers() + " does not match given multiple consumers "
204	                                                   + multipleConsumers);
205	            }
206	        }
207	
208	        Consumer answer = createNewConsumer(processor);
209	        configureConsumer(answer);
210	        return answer;
