227	    public BlockingQueue<Exchange> getQueue() {
228	        lock.lock();
229	        try {
230	            if (queue == null) {
231	                // prefer to lookup queue from component, so if this endpoint is re-created or re-started
232	                // then the existing queue from the component can be used, so new producers and consumers
233	                // can use the already existing queue referenced from the component
234	                if (getComponent() != null) {
235	                    // use null to indicate default size (= use what the existing queue has been configured with)
236	                    Integer size = (getSize() == Integer.MAX_VALUE || getSize() == SedaConstants.QUEUE_SIZE) ? null : getSize();
237	                    QueueReference ref = getComponent().getOrCreateQueue(this, size, isMultipleConsumers(), queueFactory);
238	                    queue = ref.getQueue();
239	                    String key = getComponent().getQueueKey(getEndpointUri());
240	                    LOG.debug("Endpoint {} is using shared queue: {} with size: {}", this, key,
241	                            ref.getSize() != null ? ref.getSize() : Integer.MAX_VALUE);
242	                    // and set the size we are using
243	                    if (ref.getSize() != null) {
244	                        setSize(ref.getSize());
245	                    }
246	                } else {
247	                    // fallback and create queue (as this endpoint has no component)
248	                    queue = createQueue();
249	                    LOG.debug("Endpoint {} is using queue: {} with size: {}", this, getEndpointUri(), getSize());
250	                }
251	            }
252	            return queue;
253	        } finally {
254	            lock.unlock();
255	        }
256	    }
257	
258	    protected BlockingQueue<Exchange> createQueue() {
259	        if (size > 0) {
260	            return queueFactory.create(size);
261	        } else {
262	            return queueFactory.create();
263	        }
264	    }
