266	    /**
267	     * Gets the {@link QueueReference} for this endpoint.
268	     *
269	     * @return the reference, or <tt>null</tt> if no queue reference exists.
270	     */
271	    public QueueReference getQueueReference() {
272	        if (ref == null || ref.getCount() == 0) {
273	            ref = tryQueueRefInit();
274	        }
275	
276	        return ref;
277	    }
278	
279	    private QueueReference tryQueueRefInit() {
280	        final SedaComponent component = getComponent();
281	        if (component != null) {
282	            final String key = component.getQueueKey(getEndpointUri());
283	            return component.getQueueReference(key);
284	        }
285	
286	        return null;
287	    }
288	
289	    protected AsyncProcessor getConsumerMulticastProcessor() {
290	        lock.lock();
291	        try {
292	            if (!multicastStarted && consumerMulticastProcessor != null) {
293	                // only start it on-demand to avoid starting it during stopping
294	                ServiceHelper.startService(consumerMulticastProcessor);
295	                multicastStarted = true;
296	            }
297	            return consumerMulticastProcessor;
298	        } finally {
299	            lock.unlock();
300	        }
301	    }
302	
303	    protected void updateMulticastProcessor() throws Exception {
304	        lock.lock();
305	        try {
306	            // only needed if we support multiple consumers
307	            if (!isMultipleConsumersSupported()) {
308	                return;
309	            }
310	
311	            // stop old before we create a new
312	            if (consumerMulticastProcessor != null) {
313	                ServiceHelper.stopService(consumerMulticastProcessor);
314	                consumerMulticastProcessor = null;
315	            }
316	
317	            int size = getConsumers().size();
318	            if (size >= 1) {
319	                if (multicastExecutor == null) {
320	                    // create multicast executor as we need it when we have more than 1 processor
321	                    multicastExecutor = getCamelContext().getExecutorServiceManager().newDefaultThreadPool(this,
322	                            URISupport.sanitizeUri(getEndpointUri()) + "(multicast)");
323	                }
324	                // create list of consumers to multicast to
325	                List<Processor> processors = new ArrayList<>(size);
326	                for (SedaConsumer consumer : getConsumers()) {
327	                    processors.add(consumer.getProcessor());
328	                }
329	                // create multicast processor
330	                multicastStarted = false;
331	
332	                consumerMulticastProcessor = (AsyncProcessor) PluginHelper.getProcessorFactory(getCamelContext())
333	                        .createProcessor(getCamelContext(), "MulticastProcessor",
334	                                new Object[] { processors, multicastExecutor, false });
335	            }
336	        } finally {
337	            lock.unlock();
338	        }
339	    }
