457	    @ManagedAttribute
458	    public long getTimeout() {
459	        return timeout;
460	    }
461	
462	    /**
463	     * Timeout (in milliseconds) before a SEDA producer will stop waiting for an asynchronous task to complete. You can
464	     * disable timeout by using 0 or a negative value.
