546	    /**
547	     * If enabled, spawns a new virtual thread for each message instead of using a fixed pool of consumer threads. This
548	     * model is optimized for virtual threads (JDK 21+) and I/O-bound workloads where creating threads is cheap. The
549	     * concurrentConsumers option becomes a limit on max concurrent tasks (0 = unlimited). Requires virtual threads to
550	     * be enabled via camel.threads.virtual.enabled=true.
551	     */
552	    public void setVirtualThreadPerTask(boolean virtualThreadPerTask) {
