592	    /**
593	     * Returns the current active consumers on this endpoint
594	     */
595	    public Set<SedaConsumer> getConsumers() {
596	        return consumers;
597	    }
598	
599	    /**
600	     * Returns the current active producers on this endpoint
601	     */
602	    public Set<SedaProducer> getProducers() {
