604	    }
605	
606	    void onStarted(SedaProducer producer) {
607	        producers.add(producer);
608	    }
609	
610	    void onStopped(SedaProducer producer) {
611	        producers.remove(producer);
612	    }
613	
614	    void onStarted(SedaConsumer consumer) throws Exception {
615	        consumers.add(consumer);
616	        if (isMultipleConsumers()) {
617	            updateMulticastProcessor();
618	        }
619	    }
620	
621	    void onStopped(SedaConsumer consumer) throws Exception {
622	        consumers.remove(consumer);
623	        if (isMultipleConsumers()) {
624	            updateMulticastProcessor();
625	        }
626	    }
627	
628	    public boolean hasConsumers() {
629	        return !this.consumers.isEmpty();
630	    }
631	
632	    @Override
633	    protected void doInit() throws Exception {
634	        super.doInit();
635	
636	        // When virtualThreadPerTask is enabled, default concurrentConsumers to 0 (unlimited)
637	        // since the traditional default of 1 defeats the purpose of thread-per-task mode
638	        if (virtualThreadPerTask && concurrentConsumers == 1) {
639	            concurrentConsumers = 0;
640	        }
641	
642	        if (discardWhenFull && blockWhenFull) {
643	            throw new IllegalArgumentException(
644	                    "Cannot enable both discardWhenFull=true and blockWhenFull=true."
645	                                               + " You can only either discard or block when full.");
646	        }
647	    }
648	
649	    @Override
650	    protected void doStart() throws Exception {
651	        super.doStart();
652	
653	        // force creating queue when starting
654	        if (queue == null) {
655	            queue = getQueue();
656	        }
657	
658	        ref = tryQueueRefInit();
659	    }
660	
661	    @Override
662	    public void stop() {
663	        if (getConsumers().isEmpty()) {
664	            super.stop();
665	        } else {
666	            LOG.debug("There is still active consumers.");
667	        }
668	
669	        ref = null;
670	    }
671	
672	    @Override
673	    public void shutdown() {
674	        if (isShutdown()) {
675	            LOG.trace("Service already shut down");
676	            return;
677	        }
678	
679	        // notify component we are shutting down this endpoint
680	        if (getComponent() != null) {
681	            getComponent().onShutdownEndpoint(this);
682	        }
683	
684	        if (getConsumers().isEmpty()) {
685	            super.shutdown();
686	        } else {
687	            LOG.debug("There is still active consumers.");
688	        }
689	    }
690	
691	    @Override
692	    protected void doShutdown() throws Exception {
693	        // shutdown thread pool if it was in use
694	        if (multicastExecutor != null) {
695	            getCamelContext().getExecutorServiceManager().shutdownNow(multicastExecutor);
696	            multicastExecutor = null;
697	        }
698	
699	        // clear queue, as we are shutdown, so if re-created then the queue must be updated
700	        queue = null;
701	        ref = null;
702	    }
703	
704	}
