32	import org.apache.camel.Suspendable;
33	import org.apache.camel.spi.ShutdownAware;
34	import org.apache.camel.spi.Synchronization;
35	import org.apache.camel.support.DefaultConsumer;
36	import org.apache.camel.support.UnitOfWorkHelper;
37	import org.apache.camel.util.ObjectHelper;
38	import org.slf4j.Logger;
39	import org.slf4j.LoggerFactory;
40	
41	/**
42	 * A Consumer for the SEDA component.
43	 * <p/>
44	 * In this implementation there is a little <i>slack period</i> when you suspend/stop the consumer, by which the
45	 * consumer may pickup a newly arrived messages and process it. That period is up till 1 second.
46	 */
47	public class SedaConsumer extends DefaultConsumer implements Runnable, ShutdownAware, Suspendable {
48	
49	    private static final Logger LOG = LoggerFactory.getLogger(SedaConsumer.class);
50	
51	    private final AtomicInteger taskCount = new AtomicInteger();
52	    private volatile CountDownLatch latch;
53	    private volatile boolean shutdownPending;
54	    private volatile boolean forceShutdown;
55	    private ExecutorService executor;
56	    protected final int pollTimeout;
57	
58	    public SedaConsumer(SedaEndpoint endpoint, Processor processor) {
59	        super(endpoint, processor);
60	        this.pollTimeout = endpoint.getPollTimeout();
61	    }
62	
63	    protected int getPollTimeout() {
64	        return pollTimeout;
65	    }
66	
67	    protected boolean isShutdownPending() {
68	        return shutdownPending;
69	    }
70	
71	    protected void setShutdownPending(boolean shutdownPending) {
72	        this.shutdownPending = shutdownPending;
73	    }
74	
75	    @Override
76	    public SedaEndpoint getEndpoint() {
77	        return (SedaEndpoint) super.getEndpoint();
78	    }
79	
80	    @Override
81	    public boolean deferShutdown(ShutdownRunningTask shutdownRunningTask) {
82	        // deny stopping on shutdown as we want seda consumers to run in case some other queues
83	        // depend on this consumer to run, so it can complete its exchanges
84	        return true;
85	    }
86	
87	    @Override
88	    public int getPendingExchangesSize() {
89	        // the route is shutting down, so either we should purge the queue,
90	        // or return how many exchanges are still on the queue
91	        if (getEndpoint().isPurgeWhenStopping()) {
92	            getEndpoint().purgeQueue();
93	        }
94	        return getEndpoint().getQueue().size();
95	    }
96	
97	    @Override
98	    public void prepareShutdown(boolean suspendOnly, boolean forced) {
99	        // if we are suspending then we want to keep the thread running but just not route the exchange
100	        // this logic is only when we stop or shutdown the consumer
101	        if (suspendOnly) {
102	            LOG.debug("Skip preparing to shutdown as consumer is being suspended");
103	            return;
104	        }
105	
106	        // signal we want to shutdown
107	        shutdownPending = true;
108	        forceShutdown = forced;
109	
110	        if (latch != null) {
111	            LOG.debug("Preparing to shutdown, waiting for {} consumer threads to complete.", latch.getCount());
112	
113	            // wait for all threads to end, using the shutdown strategy timeout
114	            try {
115	                long timeout = getEndpoint().getCamelContext().getShutdownStrategy().getTimeout();
116	                TimeUnit timeUnit = getEndpoint().getCamelContext().getShutdownStrategy().getTimeUnit();
117	                if (!latch.await(timeout, timeUnit)) {
118	                    LOG.warn("Timeout waiting for {} consumer threads to complete during shutdown (waited {} {}).",
119	                            latch.getCount(), timeout, timeUnit);
120	                }
121	            } catch (InterruptedException e) {
122	                Thread.currentThread().interrupt();
123	            }
124	        }
125	    }
126	
127	    @Override
128	    public boolean isRunAllowed() {
129	        // if we force shutdown then do not allow running anymore
130	        if (forceShutdown) {
131	            return false;
132	        }
133	
134	        if (isSuspending() || isSuspended()) {
135	            // allow to run even if we are suspended as we want to
136	            // keep the thread task running
137	            return true;
138	        }
139	        return super.isRunAllowed();
140	    }
141	
142	    @Override
143	    public void run() {
144	        taskCount.incrementAndGet();
145	        try {
146	            doRun();
147	        } finally {
148	            taskCount.decrementAndGet();
149	            if (latch != null) {
150	                latch.countDown();
151	                LOG.debug("Ending this polling consumer thread, there are still {} consumer threads left.", latch.getCount());
152	            }
153	        }
154	    }
155	
156	    protected void doRun() {
157	        BlockingQueue<Exchange> queue = getEndpoint().getQueue();
158	        // loop while we are allowed, or if we are stopping loop until the queue is empty
159	        while (queue != null && isRunAllowed()) {
160	
161	            // do not poll during CamelContext is starting, as we should only poll when CamelContext is fully started
162	            if (getEndpoint().getCamelContext().getStatus().isStarting()) {
163	                LOG.trace("CamelContext is starting so skip polling");
164	                try {
165	                    // sleep at most 1 sec
166	                    Thread.sleep(Math.min(pollTimeout, 1000));
167	                } catch (InterruptedException e) {
168	                    LOG.debug("Sleep interrupted, are we stopping? {}", isStopping() || isStopped());
169	                    Thread.currentThread().interrupt();
170	                }
171	                continue;
172	            }
173	
174	            // do not poll if we are suspended or starting again after resuming
175	            if (isSuspending() || isSuspended() || isStarting()) {
176	                if (shutdownPending && queue.isEmpty()) {
177	                    LOG.trace(
178	                            "Consumer is suspended and shutdown is pending, so this consumer thread is breaking out because the task queue is empty.");
179	                    // we want to shutdown so break out if there queue is empty
180	                    break;
181	                } else {
182	                    LOG.trace("Consumer is suspended so skip polling");
183	                    try {
184	                        // sleep at most 1 sec
185	                        Thread.sleep(Math.min(pollTimeout, 1000));
186	                    } catch (InterruptedException e) {
187	                        LOG.debug("Sleep interrupted, are we stopping? {}", isStopping() || isStopped());
188	                        Thread.currentThread().interrupt();
189	                    }
190	                    continue;
191	                }
192	            }
193	
194	            Exchange exchange = null;
195	            try {
196	                // hook for subclasses to prepare before polling (e.g., acquire permits)
197	                if (!beforePoll()) {
198	                    continue;
199	                }
200	
201	                // use the end user configured poll timeout
202	                exchange = queue.poll(pollTimeout, TimeUnit.MILLISECONDS);
203	                if (LOG.isTraceEnabled()) {
204	                    LOG.trace("Polled queue {} with timeout {} ms. -> {}", ObjectHelper.getIdentityHashCode(queue), pollTimeout,
205	                            exchange);
206	                }
207	                if (exchange != null) {
208	                    try {
209	                        // process the exchange (subclasses can override to dispatch to another thread)
210	                        processPolledExchange(exchange);
211	                    } catch (Exception e) {
212	                        getExceptionHandler().handleException("Error processing exchange", exchange, e);
213	                    }
214	                } else {
215	                    // hook for subclasses to cleanup after empty poll (e.g., release permits)
216	                    afterPollEmpty();
217	                    if (shutdownPending && queue.isEmpty()) {
218	                        LOG.trace(
219	                                "Shutdown is pending, so this consumer thread is breaking out because the task queue is empty.");
220	                        // we want to shutdown so break out if there queue is empty
221	                        break;
222	                    }
223	                }
224	            } catch (InterruptedException e) {
225	                LOG.debug("Sleep interrupted, are we stopping? {}", isStopping() || isStopped());
226	                Thread.currentThread().interrupt();
227	            } catch (Exception e) {
228	                if (exchange != null) {
229	                    getExceptionHandler().handleException("Error processing exchange", exchange, e);
230	                } else {
231	                    getExceptionHandler().handleException(e);
232	                }
233	            }
234	        }
235	    }
236	
237	    /**
238	     * Hook called before polling the queue. Subclasses can override to acquire resources (e.g., permits).
239	     *
240	     * @return                      true to proceed with polling, false to skip this poll iteration
241	     * @throws InterruptedException if interrupted while acquiring resources
242	     */
243	    protected boolean beforePoll() throws InterruptedException {
244	        return true;
245	    }
246	
247	    /**
248	     * Hook called when poll returned no exchange. Subclasses can override to release resources (e.g., permits).
249	     */
250	    protected void afterPollEmpty() {
251	        // nothing by default
252	    }
253	
254	    /**
255	     * Process a polled exchange. Subclasses can override to dispatch to another thread.
256	     *
257	     * @param exchange the exchange to process
258	     */
259	    protected void processPolledExchange(Exchange exchange) {
260	        final Exchange original = exchange;
261	        // prepare the exchange before sending to consumer
262	        final Exchange prepared = prepareExchange(exchange);
263	        // callback to be executed when sending to consumer and processing is done
264	        AsyncCallback callback = doneSync -> onProcessingDone(original, prepared);
265	        // process the exchange
266	        try {
267	            sendToConsumers(prepared, callback);
268	        } catch (Exception e) {
269	            getExceptionHandler().handleException("Error processing exchange", exchange, e);
270	        }
271	    }
272	
273	    /**
274	     * Strategy to invoke when the exchange is done being processed.
275	     * <p/>
276	     * This method is meant to be overridden by subclasses to be able to mimic the behavior of the legacy component
277	     * camel-vm, that is why the parameter {@code prepared} is not used by default.
278	     *
279	     * @param original the exchange before being processed
280	     * @param prepared the exchange processed
281	     */
282	    protected void onProcessingDone(Exchange original, Exchange prepared) {
283	        // log exception if an exception occurred and was not handled
284	        if (original.getException() != null) {
285	            getExceptionHandler().handleException("Error processing exchange", original,
286	                    original.getException());
287	        }
288	    }
289	
290	    /**
291	     * Strategy to prepare exchange for being processed by this consumer
292	     * <p/>
293	     * This method is meant to be overridden by subclasses to be able to mimic the behavior of the legacy component
294	     * camel-vm, that is why the prepared exchange is returned.
295	     *
296	     * @param  exchange the exchange
297	     * @return          the exchange to process by this consumer
298	     */
299	    protected Exchange prepareExchange(Exchange exchange) {
300	        // this consumer grabbed the exchange so mark it's from this route/endpoint
301	        ExchangeExtension exchangeExtension = exchange.getExchangeExtension();
302	        exchangeExtension.setFromEndpoint(getEndpoint());
303	        exchangeExtension.setFromRouteId(getRouteId());
304	        return exchange;
305	    }
306	
307	    /**
308	     * Send the given {@link Exchange} to the consumer(s).
309	     * <p/>
310	     * If multiple consumers then they will each receive a copy of the Exchange. A multicast processor will send the
311	     * exchange in parallel to the multiple consumers.
312	     * <p/>
313	     * If there is only a single consumer then its dispatched directly to it using same thread.
314	     *
315	     * @param  exchange  the exchange
316	     * @param  callback  exchange callback to continue routing
317	     * @throws Exception can be thrown if processing of the exchange failed
318	     */
319	    protected void sendToConsumers(final Exchange exchange, final AsyncCallback callback) throws Exception {
320	        // validate multiple consumers has been enabled
321	        int size = getEndpoint().getConsumers().size();
322	        if (size > 1 && !getEndpoint().isMultipleConsumersSupported()) {
323	            throw new IllegalStateException("Multiple consumers for the same endpoint is not allowed: " + getEndpoint());
324	        }
325	
326	        // if there are multiple consumers then multicast to them
327	        if (getEndpoint().isMultipleConsumersSupported()) {
328	
329	            if (LOG.isTraceEnabled()) {
330	                LOG.trace("Multicasting to {} consumers for Exchange: {}", size, exchange);
331	            }
332	
333	            // handover completions, as we need to done this when the multicast is done
334	            final List<Synchronization> completions = exchange.getExchangeExtension().handoverCompletions();
335	
336	            // use a multicast processor to process it
337	            AsyncProcessor mp = getEndpoint().getConsumerMulticastProcessor();
338	            ObjectHelper.notNull(mp, "ConsumerMulticastProcessor", this);
339	
340	            // and use the asynchronous routing engine to support it
341	            mp.process(exchange, doneSync -> {
342	                // done the uow on the completions
343	                try {
344	                    UnitOfWorkHelper.doneSynchronizations(exchange, completions);
345	                } finally {
346	                    callback.done(doneSync);
347	                }
348	            });
349	        } else {
350	            // use the regular processor and use the asynchronous routing engine to support it
351	            getAsyncProcessor().process(exchange, callback);
352	        }
353	    }
354	
355	    @Override
356	    protected void doStart() throws Exception {
357	        super.doStart();
358	        if (getEndpoint().getConcurrentConsumers() > 0) {
359	            latch = new CountDownLatch(getEndpoint().getConcurrentConsumers());
360	        }
361	        shutdownPending = false;
362	        forceShutdown = false;
363	
364	        setupTasks();
365	        getEndpoint().onStarted(this);
366	    }
367	
368	    @Override
369	    protected void doSuspend() throws Exception {
370	        getEndpoint().onStopped(this);
371	    }
372	
373	    @Override
374	    protected void doResume() throws Exception {
375	        getEndpoint().onStarted(this);
376	    }
377	
378	    @Override
379	    protected void doStop() throws Exception {
380	        // ensure queue is purged if we stop the consumer
381	        if (getEndpoint().isPurgeWhenStopping()) {
382	            getEndpoint().purgeQueue();
383	        }
384	
385	        getEndpoint().onStopped(this);
386	
387	        shutdownExecutor();
388	
389	        super.doStop();
390	    }
391	
392	    @Override
393	    protected void doShutdown() throws Exception {
394	        shutdownExecutor();
395	    }
396	
397	    /**
398	     * Shuts down the executor service.
399	     */
400	    protected void shutdownExecutor() {
401	        if (executor != null) {
402	            getEndpoint().getCamelContext().getExecutorServiceManager().shutdownNow(executor);
403	            executor = null;
404	        }
405	    }
406	
407	    /**
408	     * Creates the executor service used for consumer threads.
409	     * <p/>
410	     * Subclasses can override this method to provide a different executor, such as one using virtual threads.
411	     *
412	     * @param  poolSize the number of concurrent consumers
413	     * @return          the executor service
414	     */
415	    protected ExecutorService createExecutor(int poolSize) {
416	        return getEndpoint().getCamelContext().getExecutorServiceManager()
417	                .newFixedThreadPool(this, getEndpoint().getEndpointUri(), poolSize);
418	    }
419	
420	    /**
421	     * Setup the thread pool and ensures tasks gets executed (if needed)
422	     */
423	    protected void setupTasks() {
424	        int poolSize = getEndpoint().getConcurrentConsumers();
425	
426	        // create thread pool if needed
427	        if (executor == null) {
428	            executor = createExecutor(poolSize);
429	        }
430	
431	        // submit needed number of tasks
432	        int tasks = poolSize - taskCount.get();
433	        if (tasks <= 0) {
434	            tasks = 1;
435	        }
436	        LOG.debug("Creating {} queue pooler with poll timeout {} ms.", tasks, pollTimeout);
437	        for (int i = 0; i < tasks; i++) {
438	            executor.execute(this);
439	        }
440	    }
441	
442	}
